"""Glossary lookup for Reconfigurable Satellite Communication Payloads."""

GLOSSARY = {
    "bandwidth": "the range of frequencies or data rate a channel supports",
    "latency": "the delay from sending to receiving",
    "modulation": "encoding information onto a carrier wave or light beam",
    "mesh network": "devices relaying for each other without central infrastructure",
    "post-quantum cryptography": "algorithms designed to resist quantum-computer attacks",
    "link budget": "the accounting of gains and losses along a communication path",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Reconfigurable Satellite Communication Payloads glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Front End — part of the Reconfigurable Satellite Communication Payloads system."""
import random

class ReconfigurableSatelliteCommunicationPayloadsPiece1FrontEnd:
    """Models the Front End piece: specification check and behavior sample."""

    SPEC = {"piece": "Front End", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = ReconfigurableSatelliteCommunicationPayloadsPiece1FrontEnd(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Front End — Reconfigurable Satellite Communication Payloads")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

